import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Reef: RBD","description":"","frontmatter":{"title":"CDS Reef: RBD","date":"2022-04-22T00:00:00.000Z","updated":"2022-04-23T00:00:00.000Z","tags":["Ceph","RBD","Distributed Storage","Storage Cluster","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/CDS_Reef_-_RBD.md","filePath":"posts/2022/CDS_Reef_-_RBD.md","lastUpdated":1780459816000}'),s={name:"posts/2022/CDS_Reef_-_RBD.md"};function o(p,l,a,n,_,u){return e(),t("div",null,[...l[0]||(l[0]=[r("<p>本次会议主要讨论了Ceph RBD（块存储）在CDS Reef版本中的开发计划和改进方向。以下是会议的关键点：</p><ol><li><p><strong>RBD镜像相关问题和改进</strong>：</p><ul><li>优化快照和镜像计划，以减少性能影响。</li><li>改善rbd mirroring的状态机文档，方便开发者理解。</li><li>迁移rbd套件至使用sap area，并实现多集群支持。</li><li>在rv mirror代码库中添加状态机图，方便新手理解代码。</li><li>处理和解决rbd mirroring的bug，包括错误和边缘情况处理、脑裂条件处理等。</li></ul></li><li><p><strong>日志记录和监控</strong>：</p><ul><li>改进日志配置，使其更易于在Kubernetes环境中配置。</li><li>优化日志流，使日志更易于识别和跟踪。</li><li>提供一致的图像级别指标，并通过admin socket暴露给性能监控工具。</li></ul></li><li><p><strong>性能测试和优化</strong>：</p><ul><li>扩展RBD镜像的性能测试，支持更多图像数量。</li><li>检查和修复多副本镜像中可能存在的问题。</li></ul></li><li><p><strong>功能增强</strong>：</p><ul><li>支持加密克隆，允许使用不同的密码和加密格式。</li><li>支持NBD流，改进RBD实时迁移功能。</li><li>改进持久性宽背缓存，使用pmem模式。</li></ul></li><li><p><strong>测试套件改进</strong>：</p><ul><li>修复测试不稳定的问题，确保测试套件的稳定性。</li></ul></li><li><p><strong>容器化和自动化</strong>：</p><ul><li>改进容器化部署，优化用户交互体验。</li><li>探索将客户端组件运行在容器中的可能性。</li></ul></li><li><p><strong>NVMe和 fabrics网关</strong>：</p><ul><li>开发新的NVMe和 fabrics网关，以替代现有的iSCSI网关。</li></ul></li></ol><p>本次会议明确了CDS Reef版本中RBD开发的主要方向和任务，为后续的开发工作提供了指导。</p>",3)])])}const g=i(s,[["render",o]]);export{d as __pageData,g as default};
